# -*- coding: utf-8 -*-
"""Every text the UI looks up with T(), and where its translation comes from.

An entry is (English text, source). The English text is exactly what the C source passes to T() (tools/lang/scan_keys.py --check
verifies that). A source is one of

  'file:label'                      the PSP firmware's own text: the label in that RCO file of flash0:/vsh/resource (6.60), in each language
  ('fw+', 'file:label', 'suffix')   the firmware's text with something appended (for example "Free Space" + "  %u GB")
  ('tmpl', {lang: 'x {c} y'}, 'file:label')   a sentence around the firmware's word ({c})
  O(ja, fr, es, de, it, nl, pt, ru, ko, zht, zhs)   VitaXMB's own words, translated by hand (the PSP had no such text)

English is never listed (the UI's own words are its English). Languages the PSP never had (Finnish, Swedish, Danish, Norwegian, Polish,
Turkish) show English.
"""

LANGS = ['ja', 'en', 'fr', 'es', 'de', 'it', 'nl', 'pt', 'ru', 'ko', 'zht', 'zhs']
OWN_ORDER = ['ja', 'fr', 'es', 'de', 'it', 'nl', 'pt', 'ru', 'ko', 'zht', 'zhs']


def O(*t):
    assert len(t) == 11, t
    return dict(zip(OWN_ORDER, t))


def MONTH(*t):
    return O(*t)


